 auto original=std::make_shared<stage::Lighting>();original->back={.2f,.3f,.4f};original->front={.1f,.2f,.3f};original->direct={};original->hemispheres.resize(1);original->points.resize(1);original->points[0].flags=0;auto model=std::make_shared<CharacterModel>();ModelVertex up{},down{};up.ny=1;down.ny=-1;model->vertices={up,down};
