 c={};check(stage::environment_weather("n022a",c).preset==stage::weather::Preset::fog_sand,"Original preserves requested QQ preset");c.weatherOverride=true;c.rain=c.snow=true;auto both=stage::environment_weather("n022a",c);check(both.rainEnabled==true&&both.snowEnabled==true&&both.preset==stage::weather::Preset::clear,"host independent flags override stage preset");auto rain=both;rain.snowEnabled=false;auto snow=both;snow.rainEnabled=false;auto a=stage::weather::precipitation(rain,5,{0,1800,0},nullptr),b=stage::weather::precipitation(snow,5,{0,1800,0},nullptr),all=stage::weather::precipitation(both,5,{0,1800,0},nullptr);check(!a.empty()&&!b.empty()&&all.size()==a.size()+b.size()&&all.size()<=256,"independent bounded rain plus snow particles");check(a[0].to[1]<a[0].from[1]&&a[0].widthPixels<b[0].widthPixels,"falling rain streak and snow point styles");both.rainEnabled=both.snowEnabled=false;check(stage::weather::precipitation(both,5,{0,1800,0},nullptr).empty(),"OFF stops airborne particles immediately");
